-- Widen priority check to all 6 cadence tiers (Perth=1 .. NT=6) before seeding.
alter table research.refresh_policies drop constraint if exists refresh_policies_priority_check;
alter table research.refresh_policies add constraint refresh_policies_priority_check check (priority between 1 and 6);

-- Seed research.refresh_policies for every Australian postcode in hermes/data/au-postcodes.json.
-- Generated by scripts/generate-postcode-migration.mjs (do not hand-edit).
-- Priority: Perth metro = 1, rest of WA = 2, NSW/VIC = 3, QLD/SA = 4, TAS/ACT = 5, NT = 6.
-- Cadence (minutes): WA 720, NSW/VIC 1440, QLD/SA 2880, TAS/ACT/NT 4320.
-- next_refresh_at = now() so every row is immediately eligible; priority governs ordering.
ON CONFLICT (postcode, state) DO UPDATE SET
  active = true,
  priority = LEAST(research.refresh_policies.priority, EXCLUDED.priority);
